import{_ as i,c as s,o as a,aj as t}from"./chunks/framework.C2N4vG9O.js";const k=JSON.parse(`{"title":"Reproducing HSTU","description":"How torch-rechub implements Meta's HSTU layer and trains it for next-item prediction.","frontmatter":{"title":"Reproducing HSTU","description":"How torch-rechub implements Meta's HSTU layer and trains it for next-item prediction."},"headers":[],"relativePath":"blog/hstu_reproduction.md","filePath":"en/blog/hstu_reproduction.md"}`),n={name:"blog/hstu_reproduction.md"};function o(h,e,r,l,d,p){return a(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="reproducing-hstu-in-torch-rechub" tabindex="-1">Reproducing HSTU in torch-rechub <a class="header-anchor" href="#reproducing-hstu-in-torch-rechub" aria-label="Permalink to “Reproducing HSTU in torch-rechub”">​</a></h1><p>HSTU reads a user&#39;s viewing history in chronological order and predicts the next movie. It can use both the order of the movies and the time between views. For a first run, follow the MovieLens commands below and look for Hit@K and NDCG@K after training. To read the code alongside the paper, start with the three equations in section 2.</p><p>This example uses next-item prediction as a single task to reproduce the core HSTU layer. Its treatment of position and time, data split, and training budget differ from those in the original paper. Early versions of the project used a different output structure for the core layer. Retrain models from those experiments when upgrading.</p><h2 id="_1-source-files" tabindex="-1">1. Source files <a class="header-anchor" href="#_1-source-files" aria-label="Permalink to “1. Source files”">​</a></h2><p>The HSTU implementation uses the following modules.</p><ul><li><strong>Model</strong> — <code>torch_rechub/models/generative/hstu.py</code><ul><li><code>HSTUModel</code> contains the item token embeddings, position and time input embeddings, <code>HSTUBlock</code>, and output projection.</li></ul></li><li><strong>Layer and block</strong> — <code>torch_rechub/basic/layers.py</code><ul><li><code>HSTULayer</code> implements one sequential transduction unit from equations 2–4 of the HSTU paper.</li><li><code>HSTUBlock</code> stacks layers with <code>x = x + HSTULayer(x)</code>.</li></ul></li><li><strong>HSTU and HLLM utilities</strong> — <code>torch_rechub/utils/hstu_utils.py</code><ul><li><code>RelativeBucketedTimeAndPositionBias</code> supplies the <code>rab^{p,t}</code> bias for HSTU attention scores.</li><li><code>RelPosBias</code> is an older relative position bias used by HLLM and retained for older experiments. The current <code>HSTUModel</code> uses <code>RelativeBucketedTimeAndPositionBias</code>.</li><li><code>VocabMask</code> masks PAD or invalid items during inference and ranking.</li></ul></li><li><strong>Data and training</strong><ul><li><code>torch_rechub/utils/data.py</code> defines <code>SeqDataset</code> and <code>SequenceDataGenerator</code>.</li><li><code>torch_rechub/trainers/seq_trainer.py</code> defines <code>SeqTrainer</code>.</li><li><code>examples/generative/run_hstu_movielens.py</code> and <code>examples/generative/run_hstu_amazon_books.py</code> provide training and ranking evaluation examples.</li></ul></li></ul><h3 id="train-for-one-epoch-on-movielens" tabindex="-1">Train for one epoch on MovieLens <a class="header-anchor" href="#train-for-one-epoch-on-movielens" aria-label="Permalink to “Train for one epoch on MovieLens”">​</a></h3><p>From the repository root, run preprocessing to create the vocabulary and training data in <code>processed/</code>, then start training.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Download missing MovieLens source files. Add --no_download if you already have them.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/generative/data/ml-1m/preprocess_ml_hstu.py</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run one epoch on the real dataset using the CPU.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> outputs/hstu_ml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/generative/run_hstu_movielens.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --device</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cpu</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --epoch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --batch_size</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 16</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --save_dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> outputs/hstu_ml</span></span></code></pre></div><p>For one CUDA GPU, reuse the preprocessed MovieLens files with the settings below. Each batch contains eight histories of up to 32 recent interactions. Training samples 32 negatives per target and updates the parameters every two batches. After training, the script prints Hit@K and NDCG@K on the held-out items.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/generative/run_hstu_movielens.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --device</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cuda</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --epoch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --batch_size</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --max_seq_len</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --loss_type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sampled_softmax</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --num_negatives</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --accumulation_steps</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --amp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --save_dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> outputs/hstu_ml</span></span></code></pre></div><p>These settings were tested on an RTX 5080 (16 GB) with MovieLens-1M users 1–32 and up to 24 recent interactions per user. The subset contained 578 movies and 32 user sequences in each of the training, validation, and test splits. Peak memory allocated to PyTorch tensors was about 20 MiB across training and evaluation. This excludes the driver, the CUDA context, and memory held in reserve by the allocator. Measure the full dataset with its actual vocabulary and sequence length.</p><p>For Amazon Books, prepare the input with <code>examples/generative/data/amazon-books/preprocess_amazon_books.py</code> and train with <code>examples/generative/run_hstu_amazon_books.py</code>. The training script accepts the same single-GPU sampling options. With the default cross-entropy loss, the scoring tensor grows with <code>[batch size, sequence length, vocabulary size]</code>. Preprocessing writes the vocabulary and all three splits, so choose a separate output directory for a new experiment.</p><hr><h2 id="_2-hstulayer-and-equations-2–4" tabindex="-1">2. HSTULayer and equations 2–4 <a class="header-anchor" href="#_2-hstulayer-and-equations-2–4" aria-label="Permalink to “2. HSTULayer and equations 2–4”">​</a></h2><h3 id="_2-1-equation-2-—-joint-uvqk-projection" tabindex="-1">2.1 Equation 2 — Joint UVQK projection <a class="header-anchor" href="#_2-1-equation-2-—-joint-uvqk-projection" aria-label="Permalink to “2.1 Equation 2 — Joint UVQK projection”">​</a></h3><p><code>HSTULayer</code> applies <code>LayerNorm</code> to the input and uses one linear layer to produce <code>Q/K/U/V</code> together.</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">proj_out </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> F.silu(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">self</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.proj1(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">self</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.norm_in(x)))</span></span></code></pre></div><p>Apply <code>SiLU</code> to the entire projection before splitting it into four parts. This gives <code>U</code>, <code>V</code>, <code>Q</code>, and <code>K</code> the same nonlinearity.</p><h3 id="_2-2-equation-3-—-add-rab-p-t-to-the-attention-scores" tabindex="-1">2.2 Equation 3 — Add <code>rab^{p,t}</code> to the attention scores <a class="header-anchor" href="#_2-2-equation-3-—-add-rab-p-t-to-the-attention-scores" aria-label="Permalink to “2.2 Equation 3 — Add rab^{p,t} to the attention scores”">​</a></h3><p>The layer computes attention as follows.</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scores </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Q </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> K.transpose(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scores </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> scores </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> rab(time_diffs, seq_len)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">attn_weights </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> silu(scores) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> max_seq_len</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">AV</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> attn_weights </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> V</span></span></code></pre></div><p>Two movies watched a day apart can receive a different bias from the same movies watched a year apart. The <code>rab</code> term maps differences in position and time to biases and adds them to the attention scores. All attention heads share these bias parameters. The layer then computes the weights with <code>silu(scores) / N</code>. The mask lets each position attend only to valid items at that position or earlier, skipping padding.</p><p><code>RelativeBucketedTimeAndPositionBias</code> expects <code>time_diffs</code> to equal <code>query_time - timestamp[i]</code>. When the layer takes pairwise differences, the common query time cancels, leaving the time difference between events.</p><h3 id="_2-3-equation-4-—-gate-and-project-the-output" tabindex="-1">2.3 Equation 4 — Gate and project the output <a class="header-anchor" href="#_2-3-equation-4-—-gate-and-project-the-output" aria-label="Permalink to “2.3 Equation 4 — Gate and project the output”">​</a></h3><p>The layer projects the gated attention output as follows.</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gated </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LayerNorm(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">AV</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> U</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">output </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> f2(gated)</span></span></code></pre></div><p><code>U</code> has already passed through <code>SiLU</code>, so it can gate the normalized attention output directly. The product is the sole input to <code>proj2</code>.</p><h3 id="_2-4-residual-connection" tabindex="-1">2.4 Residual connection <a class="header-anchor" href="#_2-4-residual-connection" aria-label="Permalink to “2.4 Residual connection”">​</a></h3><p><code>HSTUBlock</code> adds the residual outside the layer.</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> layer </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> self</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.layers:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    x </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> x </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> layer(x, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">padding_mask</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">padding_mask, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">time_diffs</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">time_diffs)</span></span></code></pre></div><p>The previous layer&#39;s input passes directly to the next layer, and <code>HSTULayer</code> learns the change to add to it.</p><hr><h2 id="_3-rab-p-t-and-time-features" tabindex="-1">3. <code>rab^{p,t}</code> and time features <a class="header-anchor" href="#_3-rab-p-t-and-time-features" aria-label="Permalink to “3. rab^{p,t} and time features”">​</a></h2><h3 id="_3-1-relativebucketedtimeandpositionbias" tabindex="-1">3.1 <code>RelativeBucketedTimeAndPositionBias</code> <a class="header-anchor" href="#_3-1-relativebucketedtimeandpositionbias" aria-label="Permalink to “3.1 RelativeBucketedTimeAndPositionBias”">​</a></h3><p><code>RelativeBucketedTimeAndPositionBias</code> has two sets of learned parameters.</p><ul><li><code>pos_w</code> stores the per-head bias for relative positions <code>i - j</code> and has <code>2 * max_seq_len - 1</code> entries.</li><li><code>ts_w</code> stores the per-head bias for relative time buckets and has <code>num_time_buckets + 1</code> entries.</li></ul><p>The layer assigns time differences to buckets as follows.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dt = abs(time_diffs[i] - time_diffs[j]) / 60.0</span></span>
<span class="line"><span>bucket = sqrt(dt) or log(dt)</span></span>
<span class="line"><span>bucket = clamp(bucket / time_bucket_divisor, 0, num_time_buckets)</span></span></code></pre></div><p>With <code>time_diffs=None</code>, <code>rab</code> provides a position-only bias of shape <code>(1, H, L, L)</code>. With <code>time_diffs</code>, its shape is <code>(B, H, L, L)</code>. The current <code>HSTULayer</code> creates this module with <code>n_heads=1</code> and broadcasts its bias to all attention heads.</p><h3 id="_3-2-the-other-position-bias-in-the-source" tabindex="-1">3.2 The other position bias in the source <a class="header-anchor" href="#_3-2-the-other-position-bias-in-the-source" aria-label="Permalink to “3.2 The other position bias in the source”">​</a></h3><p><code>hstu_utils.py</code> also contains <code>RelPosBias</code> for HLLM and older experiments. For the bias used in HSTU attention, see <code>RelativeBucketedTimeAndPositionBias</code>.</p><h2 id="_4-from-a-viewing-history-to-candidate-scores" tabindex="-1">4. From a viewing history to candidate scores <a class="header-anchor" href="#_4-from-a-viewing-history-to-candidate-scores" aria-label="Permalink to “4. From a viewing history to candidate scores”">​</a></h2><p><code>HSTUModel</code> embeds a sequence of item IDs, passes the vectors through <code>HSTUBlock</code>, and scores every vocabulary item at each sequence position.</p><p>From input to output, the model uses these components in order.</p><ul><li><code>token_embedding(vocab_size, d_model, padding_idx=0)</code>.</li><li>Absolute <code>position_embedding(max_seq_len, d_model)</code>.</li><li>Optional input <code>time_embedding(num_time_buckets, d_model)</code>, controlled by <code>use_time_embedding</code>.</li><li><code>HSTUBlock(..., num_time_buckets, time_bucket_fn, time_bucket_divisor)</code>.</li><li>By default, an output projection tied to the token embeddings: <code>F.linear(hstu_output, token_embedding.weight, output_bias)</code>.</li></ul><p>Time and position enter the model at two points.</p><ul><li>In equation 3 of the core HSTU layer, <code>rab^{p,t}</code> adds relative position and time information to the attention scores.</li><li>The <code>HSTUModel</code> wrapper keeps absolute position embeddings and optional input time embeddings for compatibility with the project&#39;s data interface and existing experiments.</li></ul><p>Token <code>0</code> is PAD. The model explicitly zeros PAD rows after input embedding and after the HSTU output so that position or time embeddings at padding positions cannot carry a signal.</p><hr><h2 id="_5-data-and-training-conventions" tabindex="-1">5. Data and training conventions <a class="header-anchor" href="#_5-data-and-training-conventions" aria-label="Permalink to “5. Data and training conventions”">​</a></h2><h3 id="_5-1-time-differences-at-each-position" tabindex="-1">5.1 Time differences at each position <a class="header-anchor" href="#_5-1-time-differences-at-each-position" aria-label="Permalink to “5.1 Time differences at each position”">​</a></h3><p>The preprocessing scripts generate <code>seq_time_diffs</code> as follows.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>time_diffs[i] = query_time - timestamp[i]</span></span></code></pre></div><p>Here <code>query_time</code> is usually the timestamp of the last interaction in the current history.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>timestamps  = [100, 200, 300, 400]</span></span>
<span class="line"><span>query_time  = 400</span></span>
<span class="line"><span>time_diffs  = [300, 200, 100, 0]</span></span></code></pre></div><p>Both entries use the same query time. It cancels when the layer takes their difference, so the model can recover the time between the two interactions.</p><h3 id="_5-2-dataset-format" tabindex="-1">5.2 Dataset format <a class="header-anchor" href="#_5-2-dataset-format" aria-label="Permalink to “5.2 Dataset format”">​</a></h3><p><code>SequenceDataGenerator</code> uses four-tuples.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(seq_tokens, seq_positions, seq_time_diffs, targets)</span></span></code></pre></div><p>The data interface retains <code>seq_positions</code> for compatibility. The current <code>HSTUModel</code> generates position indices from the sequence length in its forward pass, and <code>SeqTrainer</code> does not read <code>seq_positions</code> from the batch.</p><h3 id="per-user-sequence-sampling-on-movielens" tabindex="-1">Per-user sequence sampling on MovieLens <a class="header-anchor" href="#per-user-sequence-sampling-on-movielens" aria-label="Permalink to “Per-user sequence sampling on MovieLens”">​</a></h3><p>The MovieLens preprocessor defaults to <code>user_sequence</code>. It keeps the latest training sequence for each user with a long enough history and computes next-token loss at every valid position.</p><p>For each user, the last interaction is the test target and the second-to-last is the validation target. For a history of <code>1 2 3 4 5 6 7 8</code>, <code>user_sequence</code> uses <code>1 2 3 4 5</code> as training input and <code>2 3 4 5 6</code> as the position-wise labels. The validation target is <code>7</code> and the test target is <code>8</code>. With a maximum input length of 200, the training window uses the last 201 training interactions at most. This adapts per-user sampling to the project&#39;s separate validation set, left padding, and attention bias based on the times of the observed events. These choices differ from the full official training protocol.</p><p>Run these commands from the repository root. The training example defaults to 101 epochs.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/generative/data/ml-1m/preprocess_ml_hstu.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --training_sampling</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user_sequence</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --output_dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> outputs/hstu_ml_user_sequence/data</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> outputs/hstu_ml_user_sequence/model</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/generative/run_hstu_movielens.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --dataset_path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/outputs/hstu_ml_user_sequence/data&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --save_dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> outputs/hstu_ml_user_sequence/model</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --device</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cuda</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --epoch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 101</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --batch_size</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 128</span></span></code></pre></div><p><code>preprocessing_config.json</code> records the sampling mode, maximum length, and number of held-out interactions.</p><p>Each epoch visits every eligible user once. Validation selects the model weights during training, and the logs record optimizer updates and elapsed time. The test set measures final performance.</p><h3 id="_5-3-training-objective" tabindex="-1">5.3 Training objective <a class="header-anchor" href="#_5-3-training-objective" aria-label="Permalink to “5.3 Training objective”">​</a></h3><p><code>SeqTrainer</code> computes next-token cross-entropy across the sequence.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>logits[:, i, :] -&gt; seq_tokens[:, i + 1]</span></span>
<span class="line"><span>logits[:, -1, :] -&gt; targets</span></span></code></pre></div><p>The loss excludes PAD token <code>0</code> via <code>ignore_index=0</code>. On validation and test data, <code>evaluate</code> returns the average loss and top-1 accuracy on the final held-out target. The example scripts also report HR@K and NDCG@K for ranking.</p><hr><h2 id="_6-comparison-with-meta-s-implementation" tabindex="-1">6. Comparison with Meta&#39;s implementation <a class="header-anchor" href="#_6-comparison-with-meta-s-implementation" aria-label="Permalink to “6. Comparison with Meta&#39;s implementation”">​</a></h2><p>Three operations connect the code to the paper. The <code>SiLU</code> after the joint projection implements equation 2. The relative time and position bias on the scores implements equation 3. The output projection after <code>LayerNorm(AV) * U</code> implements equation 4. The enclosing <code>HSTUBlock</code> adds the residual.</p><p>Several differences outside the core layer affect comparisons. The model keeps absolute input position embeddings and optional input time embeddings. The attention bias uses the time differences between the observed interactions. MovieLens supplies one training sequence per user and a separate validation target. Both training and evaluation use only next-item prediction. Record these choices and the training budget when reporting results.</p>`,76)])])}const u=i(n,[["render",o]]);export{k as __pageData,u as default};
